/** Visual archive prototype: local illustration assets only, never personal-photo claims.
 * mountGallery owns scroll/keyboard/dialog listeners and returns cleanup for SPA navigation.
 */
const items=[
 {src:'gallery-space.svg',title:'一个自己的地方',kind:'个人空间 / 排版习作',note:'文字、作品与生活，在同一个地方慢慢积累。原型设计稿。',href:'#/project/website'},
 {src:'gallery-reading.svg',title:'从一篇文字开始',kind:'阅读界面 / 设计示例',note:'先找到关心的问题，再沿着专题继续阅读。原型界面示意，不代表已发布的真实文章。',href:'#/writing'},
 {src:'gallery-notes.svg',title:'留下过程',kind:'视觉笔记 / 示例',note:'未来可以放工作现场、旅途片段和项目过程图。当前为排版示例，不冒充个人照片。',href:'#/project/website'},
 {src:'gallery-shop.svg',title:'让交流有下一步',kind:'商品界面 / 设计示例',note:'先把目录、试读和交付说明说清楚，再联系咨询。原型不接受真实购买。',href:'#/shop'}
];
export function gallery(inProjects=false){return `<section class="visual-archive" aria-label="作品与影像"><div class="archive-stage"><div class="archive-heading"><div><span class="eyebrow">SELECTED FRAGMENTS / 作品与影像</span><h2>文字之外，<em>还有画面。</em></h2></div><p>滚动浏览 · 点击展开<br><small>界面与排版示例，个人照片待补充</small></p></div><div class="archive-window"><div class="archive-track">${items.map((x,i)=>`<button class="archive-card archive-card-${i}" data-gallery="${i}" aria-label="展开：${x.title}"><img src="${x.src}" loading="lazy" decoding="async" alt="${x.kind}"><span><strong>${x.title}</strong><small>${x.kind} ↗</small></span></button>`).join('')}</div></div><div class="archive-bottom"><span>把做过的尝试，留在这里。</span><div><button data-gallery-step="-1" aria-label="上一组作品">←</button><button data-gallery-step="1" aria-label="下一组作品">→</button><a href="#/projects" ${inProjects?'data-section="project-directory"':''}>作品目录 ↗</a></div></div><div class="archive-progress" aria-hidden="true"><i></i></div></div></section>`}
export function mountGallery(root){
 const region=root.querySelector('.visual-archive');if(!region)return()=>{};
 const stage=region.querySelector('.archive-stage'),track=region.querySelector('.archive-track'),viewport=region.querySelector('.archive-window');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),mobile=matchMedia('(max-width: 700px)');
 const controller=new AbortController(),options={signal:controller.signal};let frame=0,origin,index=0,closing=false,oldOverflow='';let touchStart=null;
 const modal=document.createElement('dialog');modal.className='gallery-viewer';modal.setAttribute('aria-label','作品与影像浏览');document.body.append(modal);
 const cards=[...region.querySelectorAll('[data-gallery]')];
 function draw(){frame=0;const distance=track.scrollWidth-viewport.clientWidth;const span=region.offsetHeight-stage.offsetHeight;const progress=Math.max(0,Math.min(1,-region.getBoundingClientRect().top/Math.max(1,span)));if(!mobile.matches&&!reduced.matches){track.style.transform=`translateX(${-distance*progress}px)`;}else track.style.transform='none';region.querySelector('.archive-progress i').style.transform=`scaleX(${progress})`;}
 function schedule(){if(!frame)frame=requestAnimationFrame(draw)}
 function animateFrom(source,target,reverse=false){if(reduced.matches||!source||!target)return Promise.resolve();const a=source.getBoundingClientRect(),b=target.getBoundingClientRect();if(!a.width||!b.width)return Promise.resolve();const initial={transform:`translate(${a.left-b.left}px,${a.top-b.top}px) scale(${a.width/b.width},${a.height/b.height})`,opacity:0.65};return target.animate(reverse?[{transform:'none',opacity:1},initial]:[initial,{transform:'none',opacity:1}],{duration:440,easing:'cubic-bezier(.22,1,.36,1)',fill:'none'}).finished.catch(()=>{});}
 function paint(){const x=items[index];modal.innerHTML=`<header><span>黄凌波 / 作品与影像</span><button data-close aria-label="关闭图片">关闭 ×</button></header><div class="viewer-image"><img src="${x.src}" alt="${x.kind}"></div><footer><div><span class="viewer-count">${String(index+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}</span><h2>${x.title}</h2><p>${x.note}</p></div><div class="viewer-actions"><a href="${x.href}" data-detail>查看相关内容 ↗</a><div><button data-prev aria-label="上一张" ${index===0?'disabled':''}>←</button><button data-next aria-label="下一张" ${index===items.length-1?'disabled':''}>→</button></div></div></footer>`;}
 async function open(i,button){index=i;origin=button;paint();oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';modal.showModal();modal.querySelector('[data-close]').focus();const img=modal.querySelector('.viewer-image img');await img.decode().catch(()=>{});if(modal.open)animateFrom(button.querySelector('img'),img);}
 async function close(animate=true){if(closing||!modal.open)return;closing=true;if(animate&&origin?.isConnected)await animateFrom(origin.querySelector('img'),modal.querySelector('.viewer-image img'),true);modal.close();document.body.style.overflow=oldOverflow;origin?.focus({preventScroll:true});closing=false;}
 function change(delta){const next=index+delta;if(next<0||next>=items.length||closing)return;index=next;paint();modal.querySelector('[data-close]').focus();}
 region.addEventListener('click',e=>{const card=e.target.closest('[data-gallery]');if(card){open(Number(card.dataset.gallery),card);return}const step=e.target.closest('[data-gallery-step]');if(step){const direction=Number(step.dataset.galleryStep);if(mobile.matches||reduced.matches)viewport.scrollBy({left:direction*viewport.clientWidth*.8,behavior:reduced.matches?'instant':'smooth'});else window.scrollBy({top:direction*innerHeight*.65,behavior:'smooth'});}},options);
 region.addEventListener('focusin',e=>{const card=e.target.closest('[data-gallery]');if(!card||modal.open||closing||!card.matches(':focus-visible'))return;const i=cards.indexOf(card);if(!mobile.matches&&!reduced.matches){const span=region.offsetHeight-stage.offsetHeight;window.scrollTo({top:scrollY+region.getBoundingClientRect().top+span*i/(items.length-1),behavior:'instant'});}else card.scrollIntoView({block:'nearest',inline:'nearest'});},options);
 modal.addEventListener('click',e=>{if(e.target.closest('[data-close]'))close();if(e.target.closest('[data-prev]'))change(-1);if(e.target.closest('[data-next]'))change(1);if(e.target.closest('[data-detail]'))close(false);},options);
 modal.addEventListener('touchstart',e=>{if(e.target.closest('.viewer-image')&&e.touches.length===1)touchStart=[e.touches[0].clientX,e.touches[0].clientY];else touchStart=null;},{...options,passive:true});
 modal.addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart[0],dy=e.changedTouches[0].clientY-touchStart[1];touchStart=null;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)change(dx<0?1:-1);},{...options,passive:true});
 modal.addEventListener('cancel',e=>{e.preventDefault();close()},options);
 modal.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();change(-1)}if(e.key==='ArrowRight'){e.preventDefault();change(1)}},options);
 window.addEventListener('scroll',schedule,{...options,passive:true});window.addEventListener('resize',schedule,options);reduced.addEventListener('change',schedule,options);draw();
 return()=>{controller.abort();cancelAnimationFrame(frame);if(modal.open){document.body.style.overflow=oldOverflow;modal.close();}modal.remove();};
}
